"<?=$cand['id']?>" required><?php if($cand['photo']):?><img class="candidate-photo" src="<?=e($cand['photo'])?>" alt="Candidate photo"><?php else:?><div class="candidate-photo d-grid place-items-center text-secondary fw-bold">N</div><?php endif;?><div class="flex-grow-1"><div class="fw-bold"><?=e($cand['full_name'])?></div><small class="text-secondary"><?=e($cand['department'])?></small><?php if($cand['manifesto']):?><p class="small mt-2 mb-0 manifesto"><?=e(mb_strimwidth($cand['manifesto'],0,260,'…'))?></p><?php endif;?></div></label></div><?php endforeach;?></div><?php endif;?></section><hr><?php endforeach;?><?php if(array_filter($positions,fn($p)=>!$p['already_voted'])):?><button class="btn btn-primary btn-lg" type="submit">Submit my ballot</button><?php else:?><div class="alert alert-success mb-0">You have completed all positions in this election.</div><?php endif;?></form><?php render_footer(); break;
