case 'results': require_role(['admin','officer','student']);$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM elections WHERE id=?');$q->execute([$id]);$el=$q->fetch();if(!$el)throw new RuntimeException('Election not found.');if($el['status']!=='closed'&&!in_array(user()['role'],['admin','officer'],true))throw new RuntimeException('Results will be available when the election is closed.');page_title('Election results');?><div class="d-flex justify-content-between align-items-start mb-4"><div><div class="eyebrow">Official tally</div><h2 class="section-title"><?=e($el['title'])?></h2><p class="text-secondary">Results are calculated from recorded ballots.</p></div><button class="btn btn-outline-primary no-print" onclick="window.print()">Print results</button></div><?php $ps=db()->prepare('SELECT * FROM positions WHERE election_id=? ORDER BY sort_order,id');$ps->execute([$id]);foreach($ps as $p){$q=db()->prepare('SELECT c.id,c.full_name,COUNT(v.id) votes FROM candidates c LEFT JOIN votes v ON v.candidate_id=c.id WHERE c.position_id=? GROUP BY c.id ORDER BY votes DESC,c.full_name');$q->execute([$p['id']]);$list=$q->fetchAll();$total=array_sum(array_column($list,'votes'));$max=$list?max(array_column($list,'votes')):0;?><div class="card p-4 mb-3"><h5 class="fw-bold"><?=e($p['title'])?></h5><div class="text-secondary small mb-3"><?=$total?> total votes</div><?php foreach($list as $i=>$c):$pct=$total?round($c['votes']/$total*100,1):0;?><div class="mb-3"><div class="d-flex justify-content-between gap-2"><span class="fw-semibold"><?=e($c['full_name'])?> <?=$total&&$c['votes']==$max?'<span class="badge badge-soft">Leading</span>':''?></span><span class="text-secondary"><?=number_format($c['votes'])?> · <?=$pct?>%</span></div><div class="progress mt-2"><div class="progress-bar" style="width:<?=$pct?>%"></div></div></div><?php endforeach;?></div><?php } render_footer(); break;
case 'manage': require_role(['admin','officer']);page_title('Management');?><div class="mb-4"><div class="eyebrow">Electoral administration</div><h2 class="section-title">Management console</h2></div><div class="row g-3"><div class="col-lg-6"><div class="card p-4"><h5 class="fw-bold">Create election</h5><form method="post" action="index.php?page=create-election"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><?php field('title','Election title');?><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="2"></textarea></div><div class="row"><div class="col-6"><?php field('starts_at','Starts','datetime-local'); ?></div><div class="col-6"><?php field('ends_at','Ends','datetime-local'); ?></div></div><button class="btn btn-primary">Create draft election</button></form></div></div><div class="col-lg-6"><div class="card p-4"><h5 class="fw-bold">Register electoral officer</h5><?php if(user()['role']==='admin'):?><form method="post" action="index.php?page=create-officer"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><?php field('full_name','Full name');field('email','Email','email');field('password','Temporary password','password');?><button class="btn btn-outline-primary">Create officer account</button></form><?php else:?><p class="text-secondary mb-0">Officer account creation is restricted to administrators.</p><?php endif;?></div></div></div><div class="card p-4 mt-3"><h5 class="fw-bold">Elections & controls</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Election</th><th>Schedule</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach(db()->query('SELECT * FROM elections ORDER BY created_at DESC') as $r):?><tr><td><?=e($r['title'])?></td><td class="small"><?=e($r['starts_at'])?><br><?=e($r['ends_at'])?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><div class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-primary" href="index.php?page=configure&id=<?=$r['id']?>">Positions</a><form method="post" action="index.php?page=change-status"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm" onchange="this.form.submit()"><option value="">Set status…</option><?php foreach(['draft','scheduled','open','closed'] as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'disabled':''?>><?=$st?></option><?php endforeach;?></select></form><a class="btn btn-sm btn-outline-secondary" href="index.php?page=results&id=<?=$r['id']?>">Results</a></div></td></tr><?php endforeach;?></tbody></table></div></div><div class="card p-4 mt-3"><div class="d-flex justify-content-between"><h5 class="fw-bold">Student voter verification</h5><span class="badge badge-soft">Admin & officers</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Matric number</th><th>Department</th><th>Status</th><th></th></tr></thead><tbody><?php $students=db()->query("SELECT * FROM users WHERE role='student' ORDER BY created_at DESC")->fetchAll();foreach($students as $s):?><tr><td><?=e($s['full_name'])?><br><small class="text-secondary"><?=e($s['email'])?></small></td><td><?=e($s['matric_no'])?></td><td><?=e($s['department'])?></td><td><?=$s['is_verified']?'<span class="badge text-bg-success">Verified</span>':'<span class="badge text-bg-warning">Pending</span>'?></td><td><?php if(!$s['is_verified']):?><form method="post" action="index.php?page=verify"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-primary">Verify</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php render_footer();break;
case 'create-election':require_role(['admin','officer']);$title=trim($_POST['title']??'');$start=$_POST['starts_at']??'';$end=$_POST['ends_at']??'';if(!$title||!$start||!$end||strtotime($end)<=strtotime($start))throw new RuntimeException('Provide a title and valid election schedule.');$st=db()->prepare('INSERT INTO elections(title,description,starts_at,ends_at,created_by,status) VALUES(?,?,?,?,?,?)');$st->execute([$title,trim($_POST['description']??''),date('Y-m-d H:i:s',strtotime($start)),date('Y-m-d H:i:s',strtotime($end)),user()['id'],'draft']);audit('election_created',$title);flash('success','Election created. Add positions and candidates next.');redirect('index.php?page=manage');
